#include <DHT.h>

#define DHT_PIN 2 // Pin connected to DHT22 sensor

DHT dht(DHT_PIN, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  // Wait for the sensor to settle
  delay(100);

  // Read the temperature and humidity values
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Print the raw values
  Serial.print("Temp: ");
  Serial.print(temperature);
  Serial.print("°C");
  Serial.print(", Humidity: ");
  Serial.print(humidity);
  Serial.println("%");

  // Calibrate the sensor (adjust the values as needed)
  float calibrationTemp = 25.0; // Adjust this value for your temperature reference point
  float calibrationHumidity = 50.0; // Adjust this value for your humidity reference point

  temperature = temperature + (calibrationTemp - dht.readTemperature());
  humidity = humidity + (calibrationHumidity - dht.readHumidity());

  // Print the calibrated values
  Serial.print("Calibrated Temp: ");
  Serial.print(temperature);
  Serial.print("°C");
  Serial.print(", Calibrated Humidity: ");
  Serial.print(humidity);
  Serial.println("%");

  delay(1000); // Wait 1 second before taking the next reading
}
